// Shared by the DOM unit tests and the real-browser regression page.
const paragraph = "This visible passage contains meaningful article text for translation.";

export const extractionCases = [
  { name: "explicit and inherited no-translate", html: `<p translate="NO">${paragraph}</p><main translate="no"><p>${paragraph}</p></main>`, expected: [] },
  { name: "explicit yes overrides inherited no", html: `<main translate="no"><p>Retained title</p><p translate="yes">${paragraph}</p></main>`, expected: [paragraph] },
  { name: "empty translate attribute enables inline subtree", html: `<p translate="no">Retained <em translate="">Translate these words.</em> retained.</p>`, expected: ["Translate these words."] },
  { name: "notranslate compatibility class stays inherited", html: `<main class="notranslate"><p translate="yes">${paragraph}</p></main>`, expected: [] },
  { name: "invalid translate value inherits", html: `<main translate="no"><p translate="invalid">${paragraph}</p></main>`, expected: [] },
  { name: "pure addresses are skipped", html: '<p>https://example.test/path</p><p>www.example.test</p><p>sample@example.technology</p>', expected: [] },
  { name: "address in prose is kept", html: '<p>Visit https://example.test for the complete documentation.</p>', expected: ['Visit https://example.test for the complete documentation.'] },
  { name: "weak main yields to substantial article", html: `<main><h2>Loading</h2></main><article><p>${paragraph.repeat(3)}</p></article>`, expected: [paragraph.repeat(3)] },
  { name: "short main does not yield to unrelated short article", html: '<main><p>Introduction.</p></main><article><p>Advertisement.</p></article>', expected: ['Introduction.'] },
  { name: "ordinary semantic paragraph", html: `<p>${paragraph}</p>`, expected: [paragraph] },
  { name: "long generic div", html: `<div>${paragraph}</div>`, expected: [paragraph] },
  { name: "direct section prose", html: `<section>${paragraph}</section>`, expected: [paragraph] },
  { name: "direct article prose", html: `<article>${paragraph}</article>`, expected: [paragraph] },
  { name: "figure caption", html: `<figure><img alt="illustration"><figcaption>${paragraph}</figcaption></figure>`, expected: [paragraph] },
  { name: "custom block prose", html: `<news-body style="display:block">${paragraph}</news-body>`, expected: [paragraph] },
  { name: "styled span block", html: `<span style="display:block">${paragraph}</span>`, expected: [paragraph] },
  { name: "short title in article", html: `<article><div>Key findings</div><p>${paragraph}</p></article>`, expected: ["Key findings", paragraph] },
  { name: "short title in main", html: `<main><div>Study overview</div><section>${paragraph}</section></main>`, expected: ["Study overview", paragraph] },
  { name: "short title has heading weight", html: `<div style="font-weight:700">Findings</div><p>${paragraph}</p>`, expected: ["Findings", paragraph] },
  { name: "short title has larger font", html: `<div style="font-size:16px"><div style="font-size:24px">Findings</div><p>${paragraph}</p></div>`, expected: ["Findings", paragraph] },
  { name: "role heading", html: "<div role='heading'>Key findings</div>", expected: ["Key findings"] },
  { name: "unmarked short generic label is conservative", html: "<div>Key findings</div><div>Next</div>", expected: [] },
  { name: "empty main falls back to article", html: `<main></main><article><p>${paragraph}</p></article>`, expected: [paragraph] },
  { name: "empty main falls back to body", html: `<main></main><section>${paragraph}</section>`, expected: [paragraph] },
  { name: "empty article falls back to body", html: `<article></article><section>${paragraph}</section>`, expected: [paragraph] },
  { name: "menu-only main falls back to article", html: `<main><p><a href="#">Home</a> <a href="#">Account</a> <a href="#">Contact</a></p></main><article><p>${paragraph}</p></article>`, expected: [paragraph] },
  { name: "hidden main content falls back", html: `<main><p hidden>Placeholder</p></main><article><p>${paragraph}</p></article>`, expected: [paragraph] },
  { name: "adjacent title cannot mask empty main", html: `<h1>Article overview</h1><main></main><article><p>${paragraph}</p></article>`, expected: ["Article overview", paragraph] },
  { name: "valid main keeps original scope", html: `<p>Outside introduction.</p><main><p>${paragraph}</p></main><article><p>Outside article.</p></article>`, expected: [paragraph] },
  { name: "adjacent heading remains included", html: `<h1>Research overview</h1><main><p>${paragraph}</p></main>`, expected: ["Research overview", paragraph] },
  { name: "hidden text and transparent ancestors are omitted", html: `<p hidden>${paragraph}</p><p aria-hidden="true">${paragraph}</p><p style="display:none">${paragraph}</p><section style="opacity:0"><p>${paragraph}</p></section><p style="visibility:hidden">${paragraph}</p>`, expected: [] },
  { name: "paragraph navigation links are omitted", html: "<p><a href='#'>Home</a> <a href='#'>Account</a> <a href='#'>Contact</a></p>", expected: [] },
  { name: "list navigation links are omitted", html: "<ul><li><a href='#'>Account</a></li><li><a href='#'>Contact</a></li></ul>", expected: [] },
  { name: "generic linked block is omitted", html: `<div><a href="#">${paragraph}</a></div>`, expected: [] },
  { name: "single linked heading is retained", html: "<h2><a href='#'>Research overview</a></h2>", expected: ["Research overview"] },
  { name: "linked heading ignores hidden anchor decoration", html: "<h2><span><a href='#article'>Research overview</a><a aria-hidden='true' href='#anchor'>#</a></span></h2>", expected: ["Research overview"] },
  { name: "linked heading ignores empty anchors", html: "<h2><span><a href='#article'>Research overview</a><a href='#anchor'></a><a href='#anchor'> </a></span></h2>", expected: ["Research overview"] },
  { name: "heading navigation links are omitted", html: "<h2><a href='#'>Home</a> <a href='#'>Account</a></h2>", expected: [] },
  { name: "prose with a short link remains one range", html: "<p>This sentence contains a <a href='#'>reference</a> for readers to follow.</p>", expected: ["This sentence contains a reference for readers to follow."] },
  { name: "inline markup remains attached", html: "<p>Hello <em>international</em> readers.</p>", expected: ["Hello international readers."] },
  { name: "inline code remains attached to prose", html: "<p>Run <code>npm test</code> to verify the package.</p>", expected: ["Run npm test to verify the package."] },
  { name: "code-only and editable areas are excluded", html: `<pre><code>${paragraph}</code></pre><code>${paragraph}</code><p><span><code>${paragraph}</code></span></p><section contenteditable="true"><p>${paragraph}</p></section><textarea>${paragraph}</textarea>`, expected: [] },
  { name: "known non-content regions remain excluded", html: `<nav><p>${paragraph}</p></nav><aside><p>${paragraph}</p></aside><footer><p>${paragraph}</p></footer><div role="dialog"><p>${paragraph}</p></div>`, expected: [] },
  { name: "line breaks maintain independent anchors", html: "<p>First sentence.<br>Second sentence.</p>", expected: ["First sentence.", "Second sentence."] },
  { name: "nested list preserves document order without duplication", html: "<ul><li>Outer passage.<ul><li>Nested passage.</li></ul>Tail passage.</li></ul>", expected: ["Outer passage.", "Nested passage.", "Tail passage."] },
  { name: "generated output is not source", html: "<p>Original sentence.<span data-folio='translation'>Generated text.</span></p>", expected: ["Original sentence."] },
] satisfies Array<{ name: string; html: string; expected: string[] }>;
